// Demo "Convicted Felons" register: 25 entirely fictional people. Faces are generated by the same 3D face model
// the reconstruction uses, so a reconstructed face can be matched against them.
import type { Profile } from '../api'

export type Felon = {
  id: string; name: string; alias: string; sex: 'male' | 'female'; age: number; dob: string; blood: string
  crime: string; section: string; convicted: number; sentence: string; status: string; height: number; build: string
  marks: string; motive: string; method: string; psychology: string; profile: Profile; seed: number
}

function rng(seed: number) { let s = seed >>> 0; return () => { s = (s + 0x6d2b79f5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296 } }
const pick = <T,>(r: () => number, a: T[]) => a[Math.floor(r() * a.length)]

