const MARKS = ['scar_left_cheek', 'scar_right_cheek', 'scar_eyebrow', 'mole_cheek', 'birthmark_forehead', 'freckles', 'wrinkles']
const MARK_TEXT: Record<string, string> = { scar_left_cheek: 'Scar on left cheek', scar_right_cheek: 'Scar on right cheek', scar_eyebrow: 'Scar through eyebrow', mole_cheek: 'Mole on cheek', birthmark_forehead: 'Birthmark on forehead', freckles: 'Freckles', wrinkles: 'Deep facial lines' }
const BLOOD = ['O+', 'O+', 'B+', 'B+', 'A+', 'AB+', 'O-', 'A-', 'B-']
const today = new Date(2026, 9, 29)

function makeProfile(r: () => number, sex: 'male' | 'female', age: number): Profile {
  const m = sex === 'male'
  const p: Profile = {
    sex, age,
    skin: pick(r, ['light', 'medium', 'medium', 'olive', 'brown', 'brown', 'dark']),
    face_shape: pick(r, ['oval', 'round', 'square', 'heart', 'long', 'diamond']),
    forehead: pick(r, ['low', 'medium', 'high']), cheeks: pick(r, ['average', 'full', 'hollow', 'high_cheekbones']),
    hair_style: m ? pick(r, ['buzz', 'short', 'short', 'receding', 'swept', 'curly', age > 45 ? 'bald' : 'short']) : pick(r, ['long', 'long', 'bun']),
    hair_color: age > 50 && r() < 0.6 ? 'grey' : pick(r, ['black', 'black', 'black', 'dark_brown', 'dark_brown', 'brown']),
    eyebrows: m ? pick(r, ['medium', 'thick_straight', 'thick_arched', 'bushy']) : pick(r, ['thin_arched', 'medium']),
    eyes: pick(r, ['almond', 'round', 'narrow', 'hooded', 'deep_set', 'upturned']),
    eye_color: pick(r, ['brown', 'brown', 'brown', 'hazel', 'grey']), eye_spacing: pick(r, ['close', 'average', 'average', 'wide']),
    nose: pick(r, ['straight', 'broad', 'narrow', 'hooked', 'upturned', 'long']), nose_size: pick(r, ['small', 'medium', 'large']),
    mouth: pick(r, ['thin', 'medium', 'full', 'wide', 'small']),
    jaw: m ? pick(r, ['soft', 'strong', 'angular', 'narrow']) : pick(r, ['soft', 'narrow']),
    chin: pick(r, ['receding', 'medium', 'projecting', 'cleft', 'pointed']), ears: pick(r, ['small', 'medium', 'large', 'protruding']),
    beard: m ? pick(r, ['none', 'stubble', 'stubble', 'short', 'full', 'goatee']) : 'none',
    mustache: m ? pick(r, ['none', 'thin', 'thick', 'thick']) : 'none',
    sideburns: m ? pick(r, ['none', 'short', 'long']) : 'none',
    glasses: r() < 0.15 ? 'glasses' : 'none',
    marks: r() < 0.65 ? [pick(r, MARKS)] : [],
  }
  return p
}

export const FELONS: Felon[] = PEOPLE.map(([name, alias, sex, age, ci], i) => {
  const r = rng(9100 + i * 77)
  const c = CRIMES[ci], v = i % 2
  const dob = new Date(today.getFullYear() - age, Math.floor(r() * 12), 1 + Math.floor(r() * 27))
  if (dob > new Date(today.getFullYear() - age, today.getMonth(), today.getDate())) dob.setFullYear(dob.getFullYear() - 1)
  const profile = makeProfile(r, sex, age)
  return {
    id: `KA-CF-${(2041 + i * 37).toString().padStart(5, '0')}`, name, alias, sex, age,
    dob: dob.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
    blood: pick(r, BLOOD), crime: c.crime, section: c.section, sentence: c.sentence,
    convicted: 2012 + Math.floor(r() * 13), status: pick(r, ['Serving sentence · Parappana Agrahara', 'Released on parole', 'Released · under surveillance', 'Absconding']),
    height: sex === 'male' ? 162 + Math.floor(r() * 22) : 150 + Math.floor(r() * 16),
    build: pick(r, ['Slim', 'Medium', 'Athletic', 'Heavy']),
    marks: (profile.marks as string[]).map(m => MARK_TEXT[m]).join(', ') || 'None recorded',
    motive: c.motive[v], method: c.method[v], psychology: c.psychology[v], profile, seed: 9100 + i * 77,
  }
})

// ---- matching: compare the reconstruction's structured profile with each record ----
const W: Record<string, number> = { skin: 2, face_shape: 1.6, forehead: .6, cheeks: .7, hair_style: 1, hair_color: 1, eyebrows: 1, eyes: 1.5, eye_color: 1,
  eye_spacing: .8, nose: 1.5, nose_size: 1, mouth: 1, jaw: 1.5, chin: 1, ears: .6, beard: 1, mustache: .6, sideburns: .3, glasses: .3 }

export function matchScore(q: Profile, f: Felon) {
  let s = 0, t = 0
  const feats: { k: string; ok: boolean }[] = []
  for (const [k, w] of Object.entries(W)) { if (q[k] === undefined) continue; t += w; const ok = q[k] === f.profile[k]; if (ok) s += w; feats.push({ k, ok }) }
  t += 1.5; s += 1.5 * Math.max(0, 1 - Math.abs((q.age ?? 35) - f.age) / 18)
  const qm: string[] = q.marks || [], fm: string[] = f.profile.marks || []
  if (qm.length || fm.length) { t += 2; s += 2 * (qm.filter(m => fm.includes(m)).length / Math.max(qm.length, fm.length)) }
  let sim = t ? s / t : 0
  if (q.sex && q.sex !== f.sex) sim *= 0.45
  const pct = Math.round(10 * (31 + 68 * Math.pow(sim, 1.25))) / 10   // calibrated to a 0-100 confidence scale
  return { pct: Math.min(99.2, pct), feats }
}
